command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: TANZ DER KLINGEN (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Tanz der Klingen";
    const ahne = "Aphasma";
    const finalEffektName = `${gabenName} (${ahne})`;
    const zielEffektName = `${finalEffektName} - Verzaubert`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde && !globalThis._dskTanzDerKlingenRegistered) {
        globalThis._dskTanzDerKlingenRegistered = true;
        DSK_FW.EffektEnde.Register("tanzDerKlingen", finalEffektName, "Der hypnotische Tanz endet. Der Tänzer ist wieder normal angreifbar und die Feinde sind vom Bann befreit.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. VERBUNDENER CLEANUP-HOOK ---
    // Löscht die Debuffs bei den Feinden, sobald das Aphasmakind aufhört zu tanzen!
    if (!globalThis.DSK_TanzDerKlingenCleanup) {
        globalThis.DSK_TanzDerKlingenCleanup = true;
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            if ((effect.name || effect.label) === finalEffektName) {
                const parentUuid = effect.parent.uuid;
                for (let t of canvas.tokens.placeables) {
                    if (t.actor) {
                        const toDelete = t.actor.effects.filter(e => (e.name || e.label) === zielEffektName && e.getFlag("dsk", "linkedActorUuid") === parentUuid).map(e => e.id);
                        if (toDelete.length > 0) {
                            setTimeout(async () => {
                                await t.actor.deleteEmbeddedDocuments("ActiveEffect", toDelete);
                            }, 100);
                        }
                    }
                }
            }
        });
    }

    // --- 3. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 4. FUNKTION FÜR FEHLERMELDUNGEN ---
    const sendError = async (grund) => {
        const infoHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b style="font-size: 1.05em;">Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; text-align: center;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b></p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">${grund}</p>
                </div>
            </div>
        `;
        await ChatMessage.create({ whisper: whisperTargets, speaker: { alias: "System" }, content: infoHtml });
    };

    // --- 5. PRÜFUNG: WIRD APHASMAS SCHLEIER GETRAGEN? ---
    const casterEffects = casterActor.effects?.contents || Array.from(casterActor.effects || []);
    const hatSchleier = casterEffects.some(e => (e.name || e.label || "").toLowerCase().includes("aphasmas schleier"));

    if (!hatSchleier) {
        return sendError("Kein geweihter Schleier getragen! Der Tanz kann nur ausgeführt werden, während <b>Aphasmas Schleier</b> aktiv ist.");
    }

    // --- 6. ZIEL ERMITTELN & PRÜFEN ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst die Feinde (Targets) aus!");

    let validTargets = [];
    for (let targetToken of targets) {
        const targetActor = targetToken.actor;
        if (!targetActor) continue;

        if (DSK_FW.Effekt.CheckTarget(targetActor, "erwachte") || DSK_FW.Wesen.match(targetActor, ["erwacht", "erwachter", "erwachte", "katze", "katzen"])) {
            validTargets.push(targetActor);
        }
    }

    if (validTargets.length === 0) {
        return sendError(`Keines der gewählten Ziele ist ein Erwachter.`);
    }

    // --- 7. BERECHNUNGEN ---
    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    const willenskraftMalus = qsWert * 4;
    const attackeMalus = qsWert;
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // --- 8. EFFEKTE ANWENDEN ---

    // A) INFO-EFFEKT FÜR DEN CASTER
    let alterEffektCaster = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffektCaster) await alterEffektCaster.delete();

    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        description: `Führt einen schnellen Einzeltanz auf und verzaubert Feinde. Der Tänzer kann keine anderen Aktionen ausführen.`,
        flags: { dsk: { ahne: ahne } }
    }]);

    await new Promise(resolve => setTimeout(resolve, 200));

    // B) DEBUFF-EFFEKT FÜR DIE FEINDE (Mit allen Werten!)
    let affectedNames = [];
    for (let targetActor of validTargets) {
        affectedNames.push(targetActor.name);

        let alterEffektZiel = targetActor.effects.find(e => (e.name || e.label) === zielEffektName);
        if (alterEffektZiel) await alterEffektZiel.delete();

        await targetActor.createEmbeddedDocuments("ActiveEffect", [{
            name: zielEffektName,
            icon: iconBild,
            img: iconBild,
            description: `Ist vom Tanz der Klingen verzaubert. Muss Willenskraft (-${willenskraftMalus}) bestehen, um angreifen zu können. Attacken sind um ${attackeMalus} erschwert.`,
            changes: [
                { key: "system.skillModifiers.FW", mode: 0, value: `Willenskraft -${willenskraftMalus}`, priority: 20 },
                { key: "system.rangeStats.attack", mode: 2, value: -attackeMalus, priority: 20 },
                { key: "system.meleeStats.attack", mode: 2, value: -attackeMalus, priority: 20 },
                { key: "system.spellStats.damage", mode: 2, value: -attackeMalus, priority: 20 }
            ],
            flags: { dsk: { ahne: ahne, linkedActorUuid: casterActor.uuid } }
        }]);

        await new Promise(resolve => setTimeout(resolve, 150));
    }

    // --- 9. LIVE-WÄCHTER (Erinnerung an die Willenskraft-Probe) ---
    const hookId = Hooks.on("createChatMessage", async (msgObj) => {
        const activeEffekt = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
        if (!activeEffekt) {
            Hooks.off("createChatMessage", hookId);
            return;
        }

        const rawContent = msgObj.content || "";
        const cleanText = rawContent.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

        // Wenn ein Feind angreift (Würfelt eine Attacke)
        if (cleanText.includes("Angriffsprobe") || cleanText.includes("Attacke") || cleanText.includes("Fernkampf") || cleanText.includes("Zauberprobe")) {
            if (msgObj.speaker?.actor === casterActor.id) return; // Nicht der Caster selbst

            let angreiferName = msgObj.speaker?.alias || "Ein Feind";

            // Schauen, ob der Angreifer den Debuff hat
            let angreiferHatDebuff = false;
            if (msgObj.speaker?.actor) {
                const aActor = game.actors.get(msgObj.speaker.actor);
                if (aActor && aActor.effects.find(e => (e.name || e.label) === zielEffektName)) {
                    angreiferHatDebuff = true;
                }
            }

            if (angreiferHatDebuff) {
                let ownerIds = new Set(game.users.filter(u => u.isGM).map(u => u.id));
                getOwners(casterActor).forEach(id => ownerIds.add(id));

                const whisperHtml = `
                    <div style="font-family: 'Signika', sans-serif;">
                        <div class="dskbox1">
                            <p style="display:flex; align-items:center; gap:8px; margin:0;">
                                <img src="${iconBild}" style="width:28px;">
                                <b style="color:#d9534f; font-size: 1.05em;">Tanz-Wächter Erinnerung!</b>
                            </p>
                        </div>
                        <div class="dskbox2" style="margin-top:10px;">
                            <p style="font-size:0.95em;">
                                <b>${angreiferName}</b> greift an, ist aber vom <b>Tanz der Klingen</b> verzaubert!
                            </p>
                            <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                            <p style="margin-bottom: 5px; color:#B30000; font-weight:bold; text-align:center;">
                                Hat er die Willenskraft-Probe (-${willenskraftMalus}) bestanden?
                            </p>
                            <p style="font-size: 0.85em; color: #555; text-align:center;">
                                <i>(Die Erschwernisse von -${attackeMalus} auf den Angriff werden vom System automatisch abgezogen)</i>
                            </p>
                        </div>
                    </div>
                `;

                await ChatMessage.create({
                    whisper: Array.from(ownerIds).filter(id => game.users.get(id)),
                    content: whisperHtml,
                    speaker: { alias: "System" }
                });
            }
        }
    });

    // --- 10. CHAT NACHRICHT GENERIEREN ---
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> beginnt, den wirbelnden Tanz der Klingen aufzuführen.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Folgende Feinde wurden vom Tanz verzaubert:
                </p>
                <ul class="dsklist" style="margin-bottom: 8px;">
                    ${affectedNames.map(n => `<li><b>${n}</b></li>`).join("")}
                </ul>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Die Verzauberten müssen <b>Willenskraft (-${willenskraftMalus})</b> bestehen, um angreifen zu können. 
                    Gelingt dies, sind ihre Attacken dennoch um <b>${attackeMalus} erschwert</b> <i>(automatisch auf dem Bogen hinterlegt)</i>.
                </p>
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>Solange getanzt wird <span ${thinStyle}>(${qsWert} QS)</span></p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent });
    } else {
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
